  --tournaments-rim-x: 0px;
  --tournaments-rim-y: 0px;
  --tournaments-rim-scale: 1;

  /* Позиционирование мяча */
  --tournaments-ball-x: 0px;
  --tournaments-ball-y: 0px;
  --tournaments-ball-scale: 1;

  position: relative;
  isolation: isolate;
  width: 100%;
  min-height: 555px;
  overflow: hidden;

  background: #051424;
  color: #fff;
}

/* Все графические слои */
.mskba-tournaments__background,
.mskba-tournaments__veil,
.mskba-tournaments__rim,
.mskba-tournaments__ball {
  position: absolute;
  pointer-events: none;
}

/* Фоновая арена */

.mskba-tournaments__background {
  /*
   * Дополнительные 130px сверху и снизу нужны,
   * чтобы при параллаксе не появлялись пустые края.
   */
  inset: -130px 0;

  z-index: 0;

  background-color: #0a1c30;
  background-image:
    radial-gradient(
      ellipse at 55% 20%,
      #365d83 0%,
      transparent 60%
    ),
    linear-gradient(
      110deg,
      #08182a,
      #122c46 55%,
      #05101e
    );

  background-position: center;
  background-size: cover;
  background-repeat: no-repeat;

  transform: translate3d(
    0,
    var(--tournaments-bg-y),
