      rgba(4, 13, 25, .80),
      transparent 43%
    );
}

/* Щит + кольцо — отдельный PNG/WebP */

.mskba-tournaments__rim {
  z-index: 2;

  top: 10px;
  left: calc(50% - 275px);

  width: 350px /*min(350px, 33vw)*/;
  height: auto;
  max-width: none;

  object-fit: contain;

  transform-origin: 47% 20%;

  transform: translate3d(
    var(--tournaments-rim-x),
    var(--tournaments-rim-y),
    0
  ) scale(var(--tournaments-rim-scale));

  will-change: transform;
}

/* Мяч — отдельный PNG/WebP */

.mskba-tournaments__ball {
  z-index: 1;
  top: 9.5%;
  left: calc(50% - 47px);
  width: 85px;
  height: auto;
  max-width: none;

  object-fit: contain;
  transform-origin: center;

  transform: translate3d(
    var(--tournaments-ball-x),
    var(--tournaments-ball-y),
    0
  ) scale(var(--tournaments-ball-scale));

  will-change: transform;
}

