     ABOVE the original Hero, while story copy stays BELOW its sticky band. */
  isolation: auto;
  color: #fff;
}

/* Natural five-section document flow, with a sticky actor rail on desktop. */
.mskba-v3-venues__layout {
  display: grid;
  grid-template-columns: minmax(0, 50%) minmax(0, 50%);
  align-items: stretch;
  gap: 0;
  position: relative;
