  align-self: start;
  width: 100%;
  height: 0;
  min-height: 0;
  z-index: 5;
  overflow: visible;
  pointer-events: none;
}
.mskba-v3-venues__actor-canvas {
  position: relative;
  width: 100%;
  height: 75svh;
  overflow: visible;
}
.mskba-v3-venues__foreground .participant {
  position: absolute;
  bottom: -10%;
