   breakpoints the WHOLE wrapper and its clothing scale as one unit. */
.mskba-v3-venues__referee {
  --actor-natural-width: 199px;
  --actor-aspect: 199 / 573;
  --actor-width-height-ratio: .347295;
  left: 50%;
