  --host-shirt-y: 28.38%;     /* 240 / 817 */
  --host-shirt-w: 39.47%;     /* 135 / 342 */
  --host-shirt-h: 21.30%;     /* 174 / 817 */
  --host-shorts-x: 8.48%;     /* 29 / 342 */
  --host-shorts-y: 48.71%;    /* 398 / 817 */
  --host-shorts-w: 46.49%;    /* 159 / 342 */
  --host-shorts-h: 18.12%;    /* 148 / 817 */
