  .mskba-v3-venues.is-long-story .mskba-v3-story__body,
  .mskba-v3-venues__foreground .participant-wrapper {
    opacity: 1 !important;
    will-change: auto !important;
    animation: none !important;
    transition: none !important;
  }
}

/* Separate rails overlap in the same grid cell so the whole left-side
   composition stays layered around the independently docked basketball. */
.mskba-v3-venues__foreground {
    grid-column: 1;
    grid-row: 1;
}

/* Host + referee BEHIND ball z=4. */
.mskba-v3-venues__foreground--back {
    z-index: 3;
}

/* White-uniform visitor IN FRONT of ball z=4. */
.mskba-v3-venues__foreground--front {
    z-index: 5;
}

/* Контент справа */
.mskba-v3-story {
    grid-column: 2;
    grid-row: 1;
    z-index: 2;
}

/* Планшеты и телефоны: слои игроков не удваивают высоту */
@media (max-width: 1099px) {
    .mskba-v3-venues__layout {
        display: grid;
        grid-template-columns: minmax(0, 1fr);
        grid-template-rows: auto 1fr;
    }

    .mskba-v3-venues__foreground {
        grid-column: 1;
        grid-row: 1;
    }

    .mskba-v3-story {
        grid-column: 1;
        grid-row: 2;
    }
}

/* MSKBA / Venues V3 / section "Формы": майка и шорты мигают независимо.
 * ДОБАВИТЬ В КОНЕЦ текущего CSS компонента. Не заменять существующий CSS!
 * Привязка одежды к participant-wrapper и координаты --host-shirt-* / --host-shorts-*
 * остаются нетронутыми.
 */

.mskba-v3-venues {
  /* Регулировка скорости: меньше = быстрее, больше = медленнее. */
  --v3-uniform-shirt-period: 1.20s;
  --v3-uniform-shorts-period: 1.85s;
  --v3-uniform-reveal-duration: 280ms;
}

/* По умолчанию обе маски невидимы. Игрок при этом остаётся видимым. */
.mskba-v3-venues .mskba-v3-venues__player_host .participant-clothes {
  opacity: 0;
  transition: opacity var(--v3-uniform-reveal-duration) ease;
}

/* Когда центр экрана проходит секцию «Формы», показываем слой одежды. */
.mskba-v3-venues.is-uniforms-active .mskba-v3-venues__player_host .participant-clothes {
  opacity: 1;
}

/* Отдельный ритм у майки; анимация действует только внутри секции «Формы». */
.mskba-v3-venues.is-uniforms-active .mskba-v3-venues__player_host .participant-clothes > .player-tshort {
  animation: v3-uniform-contour-pulse var(--v3-uniform-shirt-period) ease-in-out infinite;
  animation-delay: -0.18s;
}

/* Отдельный более медленный ритм у шортов. */
.mskba-v3-venues.is-uniforms-active .mskba-v3-venues__player_host .participant-clothes > .player-shorts {
  animation: v3-uniform-contour-pulse var(--v3-uniform-shorts-period) ease-in-out infinite;
  animation-delay: -0.68s;
}

/* Один мягкий всплеск за цикл; без быстрого стробоскопического мерцания. */
@keyframes v3-uniform-contour-pulse {
  0%, 100% { opacity: 0.16; }
  30% { opacity: 0.38; }
  52% { opacity: 1; }
  72% { opacity: 0.55; }
}

/* При reduced motion одежда появляется статично, без мигания. */
@media (prefers-reduced-motion: reduce) {
  .mskba-v3-venues .mskba-v3-venues__player_host .participant-clothes {
    transition: none !important;
  }
  .mskba-v3-venues.is-uniforms-active .mskba-v3-venues__player_host .participant-clothes > .player-tshort,
  .mskba-v3-venues.is-uniforms-active .mskba-v3-venues__player_host .participant-clothes > .player-shorts {
    animation: none !important;
    opacity: 1 !important;
  }
}
/* Venues V3 / release v8: reserve room beneath the athletes before the
   bottom fade, without shifting the players or the docked basketball. */
@media (min-width: 1100px) {

    /* Единая настройка нижнего запаса */
    .mskba-v2-stage:has(#venues-scene.is-long-story) {
        --v3-shade-clearance: 200px;
    }

    /* Добавляем пространство под сценой */
    #venues-scene.mskba-v3-venues {
        /*padding-bottom: var(--v3-shade-clearance);*/
    }

    /* Продлеваем фон arena на ту же величину */
    .mskba-v2-stage:has(#venues-scene.is-long-story)
    > .mskba-v2-stage__background {
        height: calc(100svh + var(--v3-shade-clearance));
        margin-bottom: calc(-100svh - var(--v3-shade-clearance));
    }
}

