   * Дополнительные 130px сверху и снизу нужны,
   * чтобы при параллаксе не появлялись пустые края.
   */
  inset: -130px 0;

  z-index: 0;

  background-color: #0a1c30;
  background-image:
    radial-gradient(
      ellipse at 55% 20%,
      #365d83 0%,
      transparent 60%
    ),
