@scope (.mskba-page-builder) {
/* MSKBA Venues Map V5 — limited-width interactive card.
 * Reconciled with LIVE V4 Filament edits on 2026-10-22.
 * Outer page gutters are solid; text scrim remains INSIDE rounded card.
 */
.mskba-venues-map-section {
  position: relative; isolation: isolate; width: 100%;
  padding: 28px 0 36px; background: #f7f9fc;
}
.mskba-venues-map-section__container { position: relative; min-width: 0; }
.mskba-venues-map {
  position: relative; isolation: isolate; width: 100%; min-width: 0;
  min-height: 510px; overflow: hidden;
  border: 1px solid rgba(36,60,90,.09);
  border-radius: 21px;
  box-shadow: 0 10px 32px rgba(26,48,69,.10),0 2px 7px rgba(26,48,69,.035);
  background: #edf3f6; color: #12171f;
  font-family: var(--theme-font-family, Inter, Arial, sans-serif);
}
.mskba-venues-map__canvas {
  position: absolute; inset: 0; z-index: 0;
  width: 100%; height: 100%;
  background: linear-gradient(120deg,#f8fafb,#edf3ed);
}
.mskba-venues-map__scrim {
  position: absolute;
  inset: 0;
  z-index: 1;
  pointer-events: none;
  background: linear-gradient(90deg,
    #fff 0%,rgba(255,255,255,.995) 17%,rgba(255,255,255,.98) 27%,
    rgba(255,255,255,.88) 37%,rgba(255,255,255,.46) 48%,
    rgba(255,255,255,.10) 61%,transparent 73%);
}
.mskba-venues-map__container {
  position: relative; z-index: 2; width: 100%; min-width: 0;
  min-height: 510px; padding: 0 clamp(24px,3vw,43px);
  display: flex; align-items: center; pointer-events: none;
}
.mskba-venues-map__copy {
  position: relative;
  width: 100%;
  max-width: 595px;
  padding: 38px 0 40px;
  pointer-events: auto;
}
.mskba-venues-map__eyebrow {
  margin: 0 0 13px; color: #ff6900; font-size: 13px;
  font-weight: 800; line-height: 1.35; letter-spacing: .02em;
}
.mskba-venues-map__title {
  margin: 0 0 18px; max-width: 550px; color: #090c12;
  font-size: clamp(42px,3.6vw,62px); font-weight: 900;
  line-height: .97; letter-spacing: -.055em; text-transform: uppercase;
}
.mskba-venues-map__description {
  margin: 0; max-width: 445px; color: #496381; font-size: 16px;
  font-weight: 450; line-height: 1.48;
}
.mskba-venues-map__features {
  display: flex; flex-wrap: wrap; align-items: center; gap: 16px 19px; margin-top: 26px;
}
.mskba-venues-map__feature {
  display: inline-flex; align-items: center; gap: 8px;
  font-size: 11px; font-weight: 750; line-height: 1.28;
  white-space: nowrap; color: #142133;
}
.mskba-venues-map__feature-icon {
  flex: 0 0 30px; width: 30px; height: 30px;
  display: inline-grid; place-items: center;
}
.mskba-venues-map__feature-icon svg { width: 27px; height: 27px; color: #172339; stroke-width: 1.85; }
.mskba-venues-map__cta {
  display: inline-flex; align-items: center; justify-content: space-between;
  gap: 28px; min-height: 48px; margin-top: 29px; padding: 10px 23px;
  border-radius: 999px; color: #fff; text-decoration: none;
  background: linear-gradient(105deg,#ff9313,#ff5b00);
  font-size: 14px; font-weight: 800;
  box-shadow: 0 12px 26px rgba(237,99,0,.20);
  transition: transform .18s ease,box-shadow .18s ease;
}
.mskba-venues-map__cta:hover { color: #fff; transform: translateY(-2px); box-shadow: 0 16px 30px rgba(237,99,0,.25); }
.mskba-venues-map__cta span { font-size: 23px; line-height: 1; font-weight: 400; }
.mskba-venues-map__status { min-height: 16px; margin: 10px 0 35px; font-size: 11px; line-height: 1.4; color: #5e7491; }

/* The filters are container-aligned and are real <select> controls, not dummy chips. */
.mskba-venues-map__container .section-inner {
  position: static;
}
.mskba-venues-map__filters {
  position: absolute; left: clamp(24px,3vw,43px);
  bottom: 23px; z-index: 7;
  max-width: 100%; display: flex; align-items: center; gap: 2px;
  padding: 7px; border: 1px solid rgba(48,75,106,.09);
  border-radius: 17px; background: rgba(255,255,255,.97);
  box-shadow: 0 9px 30px rgba(25,46,70,.13);
  -webkit-backdrop-filter: blur(15px); backdrop-filter: blur(15px);
  pointer-events: auto;
}
.mskba-venues-map__filter-wrap { position: relative; display: inline-flex; align-items: center; flex: 0 0 auto; gap: 5px; padding-left: 8px; }
.mskba-venues-map__filter-icon { flex: 0 0 auto; display: inline-grid; place-items: center; width: 21px; height: 21px; color: #19304c; }
.mskba-venues-map__filter-icon svg { width: 19px; height: 19px; stroke-width: 1.9; }
.mskba-venues-map__select {
  appearance: none; -webkit-appearance: none; border: 0; border-radius: 9px;
  min-height: 40px; max-width: 180px; outline-offset: 2px;
  background: transparent; color: #182434; cursor: pointer;
  padding: 9px 22px 9px 2px; font-family: inherit; font-size: 12px; font-weight: 750;
}
.mskba-venues-map__select:disabled { cursor: default; color: #4b5870; opacity: 1; }
.mskba-venues-map__select:hover:not(:disabled) { background: #f3f7fb; }
.mskba-venues-map__filter-wrap::after {
  content: ''; position: absolute; right: 9px; top: 50%;
  width: 7px; height: 7px;
  border-right: 1.5px solid #597393;
  border-bottom: 1.5px solid #597393;
  transform: translateY(-65%) rotate(45deg);
  pointer-events: none;
}
.mskba-venues-map__reset {
  flex: 0 0 auto; min-height: 40px; display: inline-flex;
  align-items: center; gap: 8px; padding: 9px 12px;
  border: 0; border-radius: 9px; background: transparent;
  color: #486783; font-family: inherit; font-size: 12px; font-weight: 750; cursor: pointer;
}
.mskba-venues-map__reset svg { width: 17px; height: 17px; }
.mskba-venues-map__reset:hover { background: #f3f7fb; }

/* Basketball placemarks. No standard Yandex balloon is used. */
.mskba-venues-map__pin {
  width: 38px; height: 38px; display: grid; place-items: center;
  border-radius: 50% 50% 50% 5px; transform: rotate(-45deg);
  border: 2px solid #fff; background: #ff7914;
  box-shadow: 0 3px 11px rgba(12,32,49,.25);
  transition: box-shadow .18s,background .18s;
}
.mskba-venues-map__pin span {
  display: block; width: 29px; height: 29px; transform: rotate(45deg);
  background: url('/images/logo-mark-100.png') center / contain no-repeat;
}
.mskba-venues-map__pin.is-active {
  background: #ff5500;
  box-shadow: 0 0 0 6px rgba(255,100,0,.21),0 4px 12px rgba(12,32,49,.35);
}

/* Floating venue popup, always above the map and aligned to the container. */
.mskba-venues-map__card-anchor {
  position: absolute; top: 25px; right: 25px; z-index: 8;
  width: min(325px,35vw); pointer-events: auto;
}
.mskba-venues-map__venue-card {
  position: relative; border-radius: 18px; padding: 12px;
  background: #fff; color: #111b2a;
  border: 1px solid rgba(58,77,104,.10);
  box-shadow: 0 18px 50px rgba(19,40,63,.21),0 3px 9px rgba(19,40,63,.09);
  animation: mskba-venues-map-pop .22s ease-out both;
}
@keyframes mskba-venues-map-pop {
  from { opacity: 0; transform: translateY(8px) scale(.98); }
  to { opacity: 1; transform: translateY(0) scale(1); }
}
.mskba-venues-map__card-close {
  position: absolute; z-index: 3; top: -11px; right: -12px;
  width: 37px; height: 37px; display: grid; place-items: center;
  border-radius: 50%; border: 0; color: #233951;
  background: #fff; box-shadow: 0 4px 17px rgba(20,50,80,.14);
}
.mskba-venues-map__card-close:hover { color: #e76200; }
.mskba-venues-map__card-close svg { width: 20px; height: 20px; }
.mskba-venues-map__card-media {
  position: relative; height: 140px; overflow: hidden;
  border-radius: 11px; background: linear-gradient(145deg,#183a55,#1a5f76 60%,#dd6e17);
}
.mskba-venues-map__card-media img { width: 100%; height: 100%; object-fit: cover; }
.mskba-venues-map__card-media-placeholder {
  width: 100%; height: 100%; display: flex; align-items: center;
  justify-content: center; flex-direction: column; gap: 8px;
  color: #edf5fb; font-size: 12px; font-weight: 600;
  background: radial-gradient(ellipse at 75% 25%,rgba(255,131,20,.38),transparent 48%),#172e46;
}
.mskba-venues-map__card-media-placeholder svg { width: 48px; height: 48px; opacity: .75; }
.mskba-venues-map__card-label {
  position: absolute; right: 9px; top: 9px;
  border-radius: 999px; padding: 5px 10px;
  background: rgba(11,33,50,.77); color: #fff;
  font-size: 10px; font-weight: 800; line-height: 1.3;
}
.mskba-venues-map__card-body { padding: 13px 2px 2px; }
.mskba-venues-map__card-name {
  margin: 0 0 7px; color: #0f1926; font-size: 16px; line-height: 1.28;
  font-weight: 850; letter-spacing: -.018em;
}
.mskba-venues-map__card-address {
  margin: 0 0 13px; display: flex; align-items: flex-start; gap: 7px;
  color: #55708d; font-size: 12px; line-height: 1.45;
}
.mskba-venues-map__card-address svg { flex: 0 0 15px; width: 15px; height: 15px; color: #233c5e; }
.mskba-venues-map__card-tags { display: flex; flex-wrap: wrap; gap: 6px; margin: 0 0 14px; }
.mskba-venues-map__card-tag {
  border-radius: 9px; background: #f2f6fa; color: #3d5977;
  padding: 6px 9px; font-size: 11px; font-weight: 650; line-height: 1.2;
}
.mskba-venues-map__card-actions { display: flex; gap: 8px; }
.mskba-venues-map__card-link {
  flex: 1; display: inline-flex; justify-content: space-between;
  align-items: center; min-height: 39px; padding: 9px 13px;
  border: 1px solid #dce3ea; border-radius: 10px;
  color: #19263a; font-size: 12px; font-weight: 800;
  text-decoration: none; background: #fff;
}
.mskba-venues-map__card-link:hover { color: #ea6400; background: #fffaf5; border-color: #ffbc86; }
.mskba-venues-map__card-link svg { width: 17px; height: 17px; }

/* Tablet/mobile layout: the map remains usable and the popup becomes a sheet. */
@media (max-width:1199px) {
  .mskba-venues-map__copy { max-width: 510px; }
  .mskba-venues-map__title { font-size: clamp(39px,4.4vw,53px); }
  .mskba-venues-map__features { max-width: 455px; gap: 13px 15px; }
  .mskba-venues-map__card-anchor { width: min(300px,33vw); }
  .mskba-venues-map__filters { bottom: 16px; }
}
@media (max-width:767px) {
  .mskba-venues-map-section { padding: 18px 0 26px; }
  .mskba-venues-map { min-height: auto; border-radius: 17px; }
  .mskba-venues-map__canvas { top: 0; height: 100%; }
  .mskba-venues-map__container { min-height: auto; align-items: flex-start; display: block; }
  .mskba-venues-map__copy { max-width: 100%; padding: 30px 0 95px; transform: none; }
  .mskba-venues-map__title { max-width: 420px; font-size: clamp(34px,8.3vw,46px); }
  .mskba-venues-map__description { max-width: 370px; font-size: 14px; }
  .mskba-venues-map__features { max-width: 350px; display: grid; grid-template-columns: repeat(2,minmax(0,1fr)); gap: 13px 9px; margin-top: 19px; }
  .mskba-venues-map__feature { white-space: normal; }
  .mskba-venues-map__cta { margin-top: 20px; }
  .mskba-venues-map__scrim {
    background: linear-gradient(180deg,#fff 0%,rgba(255,255,255,.99) 25%,rgba(255,255,255,.83) 43%,rgba(255,255,255,.28) 65%,transparent 86%);
  }
  .mskba-venues-map__card-anchor { top: auto; right: 0; bottom: 76px; left: 0; width: auto; max-width: 400px; margin-inline: auto; }
  .mskba-venues-map__venue-card { padding: 9px; }
  .mskba-venues-map__card-media { height: 110px; }
  .mskba-venues-map__card-body { padding-top: 8px; }
  .mskba-venues-map__card-address { margin-bottom: 8px; }
  .mskba-venues-map__card-tags { margin-bottom: 10px; }
  .mskba-venues-map__filters {
    left: 0; right: 0; bottom: 13px; max-width: 100%;
    overflow-x: auto; scrollbar-width: none;
  }
  .mskba-venues-map__filters::-webkit-scrollbar { display: none; }
  .mskba-venues-map__select { max-width: 165px; }
}
@media (min-width:768px) and (max-width:991px) {
  .mskba-venues-map__container { padding-left: 28px; padding-right: 28px; }
}
@media (max-width:450px) {
  .mskba-venues-map__container { padding-left: 16px; padding-right: 16px; }
}
@media (prefers-reduced-motion:reduce) {
  .mskba-venues-map__cta { transition: none; }
  .mskba-venues-map__venue-card { animation: none; }
  .mskba-venues-map__pin { transition: none; }
}
}
@scope (.mskba-page-builder) {
/* MSKBA / venues-scene-v3 / connected Hero + players / long-scroll storytelling.
   Replace ONLY CSS of this component. Page Builder adds @scope automatically.
   No cards, no stacked panels, no CSS that scrolls the document artificially. */

.mskba-v3-venues {
  position: relative;
  width: 100%;
  /* No isolated stacking context: the three actors must be able to sit
     ABOVE the original Hero, while story copy stays BELOW its sticky band. */
  isolation: auto;
  color: #fff;
}

/* Natural five-section document flow, with a sticky actor rail on desktop. */
.mskba-v3-venues__layout {
  display: grid;
  grid-template-columns: minmax(0, 50%) minmax(0, 50%);
  align-items: stretch;
  gap: 0;
  position: relative;
}

.mskba-v3-venues__foreground {
  position: sticky;
  /* The actor rail starts high enough that fingertips align with the ball
     after the slider lower edge pins to the viewport top. */
  top: calc(var(--v3-actors-sticky-top, clamp(70px, 12svh, 125px)) - var(--v3-exit-scroll, 0px));
  align-self: start;
  width: 100%;
  height: 0;
  min-height: 0;
  z-index: 5;
  overflow: visible;
  pointer-events: none;
}
.mskba-v3-venues__actor-canvas {
  position: relative;
  width: 100%;
  height: 75svh;
  overflow: visible;
}
.mskba-v3-venues__foreground .participant {
  position: absolute;
  bottom: -10%;
}
/* Intrinsic image coordinate systems (PNG sizes verified against Site Media).
   At desktop each image keeps its previous natural dimensions; at smaller
   breakpoints the WHOLE wrapper and its clothing scale as one unit. */
.mskba-v3-venues__referee {
  --actor-natural-width: 199px;
  --actor-aspect: 199 / 573;
  --actor-width-height-ratio: .347295;
  left: 50%;
  z-index: 1;
  transform: translateX(-50%);
}
.mskba-v3-venues__player_host {
  --actor-natural-width: 342px;
  --actor-aspect: 342 / 817;
  --actor-width-height-ratio: .418605;
  right: 0;
  z-index: 2;
  transform: translateX(15%);

  /* Garment coordinates relative to the original 342 x 817 player image.
     Only these 8 values need changing to fine-tune the contours. */
  --host-shirt-x: 8.79%;      /* 28 / 342 */
  --host-shirt-y: 28.38%;     /* 240 / 817 */
  --host-shirt-w: 39.47%;     /* 135 / 342 */
  --host-shirt-h: 21.30%;     /* 174 / 817 */
  --host-shorts-x: 8.48%;     /* 29 / 342 */
  --host-shorts-y: 48.71%;    /* 398 / 817 */
  --host-shorts-w: 46.49%;    /* 159 / 342 */
  --host-shorts-h: 18.12%;    /* 148 / 817 */
}
.mskba-v3-venues__player_visitor {
  --actor-natural-width: 395px;
  --actor-aspect: 395 / 821;
  --actor-width-height-ratio: .481121;
  left: 0;
  z-index: 3;
  transform: translateX(-25%);
}

/* The JS animates this ONE wrapper, never its <img> children. */
.mskba-v3-venues__foreground .participant-wrapper {
  position: relative;
  display: block;
  flex: 0 0 auto;
  width: var(--actor-natural-width);
  aspect-ratio: var(--actor-aspect);
  height: auto;
  pointer-events: none;
  transform: translate3d(0, var(--participant-travel-y, 0%), 0);
  will-change: transform;
}
.mskba-v3-venues__referee .participant-wrapper {
  --participant-travel-y: var(--venues-v3-referee-y, 0%);
}
.mskba-v3-venues__player_host .participant-wrapper {
  --participant-travel-y: var(--venues-v3-host-y, 30%);
}
.mskba-v3-venues__player_visitor .participant-wrapper {
  --participant-travel-y: var(--venues-v3-visitor-y, 15%);
}

.mskba-v3-venues__foreground .participant-wrapper > img {
  display: block;
  width: 100%;
  height: 100%;
  max-width: none;
  max-height: none;
  object-fit: contain;
  transform: none;
}

/* Outfit is an overlay, not another layout row or animated sibling. */
.mskba-v3-venues__foreground .participant-clothes {
  position: absolute;
  inset: 0;
  z-index: 2;
  pointer-events: none;
  opacity: var(--v3-clothes-opacity, 1);
}
.mskba-v3-venues__foreground .participant-clothes > img {
  position: absolute;
  display: block;
  max-width: none;
  max-height: none;
  object-fit: fill;
  transform: none;
  pointer-events: none;
}
.mskba-v3-venues__foreground .participant-clothes .player-tshort {
  left: var(--host-shirt-x);
  top: var(--host-shirt-y);
  width: var(--host-shirt-w);
  height: var(--host-shirt-h);
}
.mskba-v3-venues__foreground .participant-clothes .player-shorts {
  left: var(--host-shorts-x);
  top: var(--host-shorts-y);
  width: var(--host-shorts-w);
  height: var(--host-shorts-h);
}

/* The right side is a LONG, real scrollable HTML block of five sections.
   Sections occupy consecutive viewport-height portions of the PAGE.
   There is no transform/position:absolute on any section itself. */
.mskba-v3-story {
  position: relative;
  z-index: 3;
  width: 100%;
  min-width: 0;
}
.mskba-v3-story__section {
  position: relative;
  min-height: 100svh;
  display: flex;
  flex-direction: column;
  justify-content: center;
  /*padding: clamp(110px, 16svh, 175px) clamp(12px, 3vw, 52px) clamp(110px, 14svh, 170px);*/
  padding: 0 clamp(12px, 3vw, 52px) clamp(110px, 14svh, 170px);
  transform: translate(0, -50px);
  box-sizing: border-box;
  overflow: visible; /* Ghost must travel beyond right-hand column/container. */
  background: transparent;
  border: 0;
  border-radius: 0;
  box-shadow: none;
}
.mskba-v3-story__ghost {
  position: absolute;
  left: -4%;
  top: clamp(230px, 30svh, 330px);
  z-index: 0;
  display: block;
  width: max-content;
  max-width: none;
  color: rgba(220, 236, 255, .14);
  font-size: clamp(76px, 7.9vw, 148px);
  font-weight: 950;
  letter-spacing: -.07em;
  line-height: .9;
  white-space: nowrap;
  text-transform: uppercase;
  pointer-events: none;
  user-select: none;
}
/* JavaScript enables motion ONLY for the ghost & supporting copy.
   The section itself always scrolls naturally with the document. */
.mskba-v3-venues.is-long-story .mskba-v3-story__ghost {
  transform: translate3d(var(--v3-ghost-x, 42vw), 0, 0);
  will-change: transform;
}
.mskba-v3-story__body {
  position: relative;
  z-index: 1;
  display: flex;
  flex-direction: column;
  align-items: flex-start;
  gap: clamp(12px, 1.4vw, 20px);
  max-width: 510px;
}
.mskba-v3-venues.is-long-story .mskba-v3-story__body {
  transform: translate3d(0, var(--v3-body-y, 0px), 0);
  opacity: var(--v3-body-opacity, 1);
}
.mskba-v3-story__eyebrow {
  margin: 0;
  color: #ff8b24;
  font-size: 12px;
  font-weight: 800;
  letter-spacing: .14em;
  text-transform: uppercase;
}
.mskba-v3-story__title {
  margin: 0;
  color: #fff;
  font-size: clamp(42px, 4.6vw, 76px);
  font-weight: 900;
  line-height: .96;
  letter-spacing: -.04em;
  text-transform: uppercase;
}
.mskba-v3-story__description {
  margin: 0;
  max-width: 440px;
  color: #e5edf7;
  font-size: clamp(15px, 1.15vw, 18px);
  line-height: 1.55;
}
.mskba-v3-story__hint {
  margin: 0;
  color: rgba(219, 236, 250, .78);
  font-size: 14px;
  line-height: 1.45;
}
.mskba-v3-story__cta {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 20px;
  width: fit-content;
  margin-top: 6px;
  padding: 15px 24px;
  color: #fff;
  background: #ff7412;
  border-radius: 32px;
  box-shadow: 0 12px 26px rgba(255, 116, 18, .21);
  text-decoration: none;
  font-size: 14px;
  font-weight: 750;
  transition: background-color .2s ease;
}
.mskba-v3-story__cta:hover,
.mskba-v3-story__cta:focus-visible {
  background: #f68b32;
  color: #fff;
}
.mskba-v3-story__cta:focus-visible {
  outline: 3px solid #fff;
  outline-offset: 4px;
}
.mskba-v3-story__cta span {
  font-size: 19px;
  line-height: .8;
}
.mskba-v3-story__counter {
  position: absolute;
  bottom: clamp(38px, 7svh, 84px);
  right: clamp(20px, 3vw, 48px);
  color: rgba(213, 233, 250, .63);
  font-size: 11px;
  font-weight: 800;
  letter-spacing: .2em;
}
.mskba-v3-venues__copy-shade {
  position: absolute;
  pointer-events: none;
  bottom: 0;
  left: 0;
  right: 0;
  height: 0; /*105px;*/
  background: linear-gradient(
  0deg,
  #f7f9fc 0%,
  #f7f9fc 25%,
  rgba(247, 249, 252, 0.85) 45%,
  rgba(247, 249, 252, 0.45) 70%,
  rgba(247, 249, 252, 0) 100%
);
  z-index: 5;
}

/* Hero scrolls naturally. The original ball detaches into the sticky
   participant composition, then exits with the athletes at the final story. */
@media (min-width: 1100px) {
  .mskba-v2-stage:has(#venues-scene.mskba-v3-venues) {
    /* Keep the scene on the ordinary page scroll. */
    /* The original Hero is free to leave after the ball detaches. */
    /* Actor pin position remains adjustable independently of ball pinViewportY. */
    --v3-actors-sticky-top: clamp(150px, 20svh, 250px);
    --v3-exit-scroll: 0px;
    /* Clip oversized ghost lettering only at FULL stage/viewport edge,
       not at each 50%-width right panel or Bootstrap .container. */
    overflow-x: clip;
  }
  .mskba-v2-stage:has(#venues-scene.mskba-v3-venues) > .mskba-v2-stage__hero {
    /* No shared pin with the ball: release the original Hero normally. */
    position: relative !important;
    top: auto !important;
    z-index: 4;
  }

  /* The SINGLE existing ball is portaled out by the component controller.
     Page JS still updates rotation, frame, scale, and lighting. */
  .mskba-v2-stage .mskba-rolling-ball.is-v3-ball-docked {
    position: fixed !important;
    left: var(--v3-ball-screen-x, 0px) !important;
    top: calc(var(--v3-ball-screen-y, 185px) - var(--v3-exit-scroll, 0px)) !important;
    z-index: 4 !important;
    width: 0;
    height: 0;
    pointer-events: none;
  }
  /* Keep the section wrapper out of its own stacking context. Hero is
     above scrolling RIGHT-hand copy, but the sticky actor rail (z=5)
     can extend in front of the hero/ball as fingertips reach the ball. */
  .mskba-v2-stage:has(#venues-scene.mskba-v3-venues) > #venues {
    position: relative;
    z-index: auto;
  }
}

/* Arena uses the same release offset as Hero and actors.
   The background MUST unpin on exit, not stay behind the next page.
   The arena is an independent page-level image.
   Preserve its viewport crop during the long (5vh) story.
   Original URL, object-fit and JS parallax remain page-owned. */
@media (min-width: 1100px) {
  .mskba-v2-stage:has(#venues-scene.mskba-v3-venues) > .mskba-v2-stage__background {
    position: sticky;
    top: calc(-1 * var(--v3-exit-scroll, 0px));
    bottom: auto;
    left: 0;
    right: 0;
    width: 100%;
    height: 100svh;
    margin-bottom: -100svh;
    overflow: hidden;
  }
  .mskba-v2-stage:has(#venues-scene.mskba-v3-venues) .mskba-v2-stage__background-image {
    /*top: -220px;
    height: calc(100% + 440px);*/
    top: -220px;
    height: calc(100% + 360px);
    /*height: 100%;*/
  }
}

/* Future tablet/mobile design can be developed independently.
   For now: no pinning, sections still scroll normally, never as cards. */
@media (max-width: 1099px) {
  .mskba-v3-venues {
    overflow-x: hidden; /* The two pictures may extend beyond viewport width. */
  }
  .mskba-v3-venues__layout {
    display: flex;
    flex-direction: column;
  }
  .mskba-v3-venues__foreground {
    position: relative;
    top: auto;
    align-self: auto;
    width: 100%;
    height: clamp(330px, 60vw, 580px);
  }
  .mskba-v3-venues__actor-canvas {
    height: 100%;
  }
  .mskba-v3-venues__foreground .participant {
    bottom: 0;
  }
  .mskba-v3-venues__foreground .participant-wrapper {
    width: min(var(--actor-natural-width),
      calc(62vw * var(--actor-width-height-ratio)),
      calc(530px * var(--actor-width-height-ratio)));
  }
  .mskba-v3-story__section {
    min-height: 78svh;
    padding: clamp(88px, 14svh, 125px) 6% clamp(80px, 12svh, 130px);
  }
  .mskba-v3-story__ghost {
    font-size: clamp(62px, 10vw, 118px);
  }
}
@media (max-width: 640px) {
  .mskba-v3-venues__foreground {
    height: clamp(250px, 70vw, 430px);
  }
  .mskba-v3-venues__foreground .participant-wrapper {
    width: min(var(--actor-natural-width),
      calc(76vw * var(--actor-width-height-ratio)));
  }
  .mskba-v3-venues__player_visitor { left: -4%; }
  .mskba-v3-venues__player_host { right: -2%; }
  .mskba-v3-story__section {
    min-height: 76svh;
    padding: 90px 6% 90px;
  }
  .mskba-v3-story__title { font-size: clamp(38px, 9vw, 54px); }
  .mskba-v3-story__description { font-size: 14px; }
  .mskba-v3-story__ghost { font-size: clamp(54px, 14vw, 92px); }
  .mskba-v3-story__counter { bottom: 34px; }
}
@media (prefers-reduced-motion: reduce) {
  .mskba-v3-venues.is-long-story .mskba-v3-story__ghost,
  .mskba-v3-venues.is-long-story .mskba-v3-story__body,
  .mskba-v3-venues__foreground .participant-wrapper {
    opacity: 1 !important;
    will-change: auto !important;
    animation: none !important;
    transition: none !important;
  }
}

/* Separate rails overlap in the same grid cell so the whole left-side
   composition stays layered around the independently docked basketball. */
.mskba-v3-venues__foreground {
    grid-column: 1;
    grid-row: 1;
}

/* Host + referee BEHIND ball z=4. */
.mskba-v3-venues__foreground--back {
    z-index: 3;
}

/* White-uniform visitor IN FRONT of ball z=4. */
.mskba-v3-venues__foreground--front {
    z-index: 5;
}

/* Контент справа */
.mskba-v3-story {
    grid-column: 2;
    grid-row: 1;
    z-index: 2;
}

/* Планшеты и телефоны: слои игроков не удваивают высоту */
@media (max-width: 1099px) {
    .mskba-v3-venues__layout {
        display: grid;
        grid-template-columns: minmax(0, 1fr);
        grid-template-rows: auto 1fr;
    }

    .mskba-v3-venues__foreground {
        grid-column: 1;
        grid-row: 1;
    }

    .mskba-v3-story {
        grid-column: 1;
        grid-row: 2;
    }
}

/* MSKBA / Venues V3 / section "Формы": майка и шорты мигают независимо.
 * ДОБАВИТЬ В КОНЕЦ текущего CSS компонента. Не заменять существующий CSS!
 * Привязка одежды к participant-wrapper и координаты --host-shirt-* / --host-shorts-*
 * остаются нетронутыми.
 */

.mskba-v3-venues {
  /* Регулировка скорости: меньше = быстрее, больше = медленнее. */
  --v3-uniform-shirt-period: 1.20s;
  --v3-uniform-shorts-period: 1.85s;
  --v3-uniform-reveal-duration: 280ms;
}

/* По умолчанию обе маски невидимы. Игрок при этом остаётся видимым. */
.mskba-v3-venues .mskba-v3-venues__player_host .participant-clothes {
  opacity: 0;
  transition: opacity var(--v3-uniform-reveal-duration) ease;
}

/* Когда центр экрана проходит секцию «Формы», показываем слой одежды. */
.mskba-v3-venues.is-uniforms-active .mskba-v3-venues__player_host .participant-clothes {
  opacity: 1;
}

/* Отдельный ритм у майки; анимация действует только внутри секции «Формы». */
.mskba-v3-venues.is-uniforms-active .mskba-v3-venues__player_host .participant-clothes > .player-tshort {
  animation: v3-uniform-contour-pulse var(--v3-uniform-shirt-period) ease-in-out infinite;
  animation-delay: -0.18s;
}

/* Отдельный более медленный ритм у шортов. */
.mskba-v3-venues.is-uniforms-active .mskba-v3-venues__player_host .participant-clothes > .player-shorts {
  animation: v3-uniform-contour-pulse var(--v3-uniform-shorts-period) ease-in-out infinite;
  animation-delay: -0.68s;
}

/* Один мягкий всплеск за цикл; без быстрого стробоскопического мерцания. */
@keyframes v3-uniform-contour-pulse {
  0%, 100% { opacity: 0.16; }
  30% { opacity: 0.38; }
  52% { opacity: 1; }
  72% { opacity: 0.55; }
}

/* При reduced motion одежда появляется статично, без мигания. */
@media (prefers-reduced-motion: reduce) {
  .mskba-v3-venues .mskba-v3-venues__player_host .participant-clothes {
    transition: none !important;
  }
  .mskba-v3-venues.is-uniforms-active .mskba-v3-venues__player_host .participant-clothes > .player-tshort,
  .mskba-v3-venues.is-uniforms-active .mskba-v3-venues__player_host .participant-clothes > .player-shorts {
    animation: none !important;
    opacity: 1 !important;
  }
}
/* Venues V3 / release v8: reserve room beneath the athletes before the
   bottom fade, without shifting the players or the docked basketball. */
@media (min-width: 1100px) {

    /* Единая настройка нижнего запаса */
    .mskba-v2-stage:has(#venues-scene.mskba-v3-venues) {
        --v3-shade-clearance: 200px;
    }

    /* Добавляем пространство под сценой */
    #venues-scene.mskba-v3-venues {
        /*padding-bottom: var(--v3-shade-clearance);*/
    }

    /* Продлеваем фон arena на ту же величину */
    .mskba-v2-stage:has(#venues-scene.mskba-v3-venues)
    > .mskba-v2-stage__background {
        height: calc(100svh + var(--v3-shade-clearance));
        margin-bottom: calc(-100svh - var(--v3-shade-clearance));
    }
}

/* First-paint parity with the component controller: no hiding or fade-in.
   Non-sticky and reduced-motion views render the existing peak pose. */
@media (max-width: 1099px), (prefers-reduced-motion: reduce) {
  .mskba-v3-venues__referee .participant-wrapper {
    --participant-travel-y: 25%;
  }
  .mskba-v3-venues__player_host .participant-wrapper {
    --participant-travel-y: -1%;
  }
  .mskba-v3-venues__player_visitor .participant-wrapper {
    --participant-travel-y: 3%;
  }
}

/* MSKBA_V3_HEIGHT_RESPONSIVE_302: viewport-height composition.
   Shrink the entire actor canvas as one graphic: PNG, clothing and the
   percentage-based motion remain in precisely the same proportions.
   Landscape, short desktop and rotated large-screen phones are covered. */
@media (min-width: 1100px) {
  .mskba-v2-stage:has(#venues-scene.mskba-v3-venues) {
    --v3-scene-viewport-scale: 1;
  }

  /* CSS typed arithmetic is supported by current Chrome and iOS Safari.
     Compute the scale from usable viewport HEIGHT rather than viewport width.
     Keep original artwork at heights >= 902px. */
  @supports (width: calc(100vw / 1px * 1px)) {
    .mskba-v2-stage:has(#venues-scene.mskba-v3-venues) {
      --v3-scene-viewport-scale: clamp(0.30, calc((100svh - 85px) / 817px), 1);
    }
  }

  .mskba-v3-venues__actor-canvas {
    transform: scale(var(--v3-scene-viewport-scale, 1));
    /* 68% X = ball/raised-hands area, 110% Y = current actor feet.
       A common origin keeps both hands close to the one docked ball. */
    transform-origin: 68% 110%;
  }

  /* The original ball sprite is never duplicated; scale its rendered radius
     by the SAME factor without changing rotation, frames, brightness or JS. */
  .mskba-v2-stage .mskba-rolling-ball.is-v3-ball-docked::before {
    transform: translate(-50%, -50%)
      scale(calc(var(--ball-scale, .48) * var(--ball-visual-size-factor, 1.1327434) * var(--v3-scene-viewport-scale, 1)));
  }

  /* Move the fixed ball's centre toward the players' scaled fingertips.
     At scale=1 this is EXACTLY the existing JS pin Y; at smaller heights
     the anchor is 95px. Retain the shared sticky-release displacement. */
  .mskba-v2-stage .mskba-rolling-ball.is-v3-ball-docked {
    top: calc(
      (var(--v3-ball-screen-y, 185px) * var(--v3-scene-viewport-scale, 1))
      + (95px * (1 - var(--v3-scene-viewport-scale, 1)))
      - var(--v3-exit-scroll, 0px)
    ) !important;
  }
}

/* Existing 150px minimum sticky top can put the feet off-screen
   on landscape/short viewports. This meets the original 20svh top at
   h=780px and gradually lowers the entire composition at small heights. */
@media (min-width: 1100px) and (max-height: 780px) {
  .mskba-v2-stage:has(#venues-scene.mskba-v3-venues) {
    --v3-actors-sticky-top: calc(21.3svh - 10px);
  }
}

/* Graceful approximate scale for browsers without typed CSS division.
   Current iOS 27/Chromium use the continuous formula above instead. */
@supports not (width: calc(100vw / 1px * 1px)) {
  @media (min-width: 1100px) and (max-height: 820px) {
    .mskba-v2-stage:has(#venues-scene.mskba-v3-venues) { --v3-scene-viewport-scale: .87; }
  }
  @media (min-width: 1100px) and (max-height: 700px) {
    .mskba-v2-stage:has(#venues-scene.mskba-v3-venues) { --v3-scene-viewport-scale: .75; }
  }
  @media (min-width: 1100px) and (max-height: 600px) {
    .mskba-v2-stage:has(#venues-scene.mskba-v3-venues) { --v3-scene-viewport-scale: .63; }
  }
  @media (min-width: 1100px) and (max-height: 500px) {
    .mskba-v2-stage:has(#venues-scene.mskba-v3-venues) { --v3-scene-viewport-scale: .48; }
  }
}

/* Landscape phone/tablet: the unpinned composition must itself fit
   the visible height. Do not affect the established portrait layout,
   the original mobile Hero ball, or mobile section order. */
@media (max-width: 1099px) and (orientation: landscape) {
  .mskba-v3-venues__foreground {
    height: min(clamp(330px, 60vw, 580px), calc(100svh - 24px));
  }
  .mskba-v3-venues__foreground .participant-wrapper {
    width: min(
      var(--actor-natural-width),
      calc(62vw * var(--actor-width-height-ratio)),
      calc((100svh - 48px) * var(--actor-width-height-ratio))
    );
  }
}
